import random
import string
from typing import List, Tuple

# This generator produces valid Wavefront MTL text bytes intended for:
# - FUZZ_PARAM_STR used as MTL text (MaterialStreamReader, LoadMtl)
# - FUZZ_PARAM_STR used as OBJ text paired with provided MTL (ObjReader::ParseFromString)
# - FUZZ_PARAM_FILENAME data blobs (MaterialFileReader) — contents are valid MTL
# Focus is on generating diverse yet valid MTL covering many directives and texture options.

MAX_BYTES = 4096

_material_names = [
    "default", "mat", "mat1", "mat_red", "mat_green", "mat_blue",
    "metal", "plastic", "glass", "emissive", "rough", "smooth",
    "pbr1", "coat", "clearcoat", "subsurf", "alpha", "two_sided"
]

_tex_basenames = [
    "albedo", "diffuse", "specular", "normal", "roughness", "metallic",
    "emissive", "opacity", "displacement", "ambient", "reflection",
    "gloss", "ao", "height", "bump"
]

_colorspaces = ["auto", "linear", "sRGB", "ACEScg", "filmic", "raw"]
_imfchans = ["r", "g", "b", "m", "l", "z"]
_types = ["sphere", "cube", "box", "cylinder", "plane"]

# Helpers to format numbers the way MTL commonly sees them

def f01(r: random.Random) -> float:
    return r.random()

def fpos(r: random.Random, lo=0.0, hi=10.0) -> float:
    return lo + (hi - lo) * r.random()


def fmt(x: float) -> str:
    # Compact decimal formatting
    s = ("%g" % x)
    if s == "-0":
        s = "0"
    return s


def rand_color(r: random.Random) -> Tuple[float, float, float]:
    return (f01(r), f01(r), f01(r))


def maybe_comment(r: random.Random) -> str:
    if r.random() < 0.2:
        return f"# comment {r.randint(0, 1<<30)}\n"
    return ""


def tex_options(r: random.Random) -> str:
    parts: List[str] = []
    # Common options
    if r.random() < 0.6:
        parts += ["-o", fmt(fpos(r, -2, 2)), fmt(fpos(r, -2, 2)), fmt(fpos(r, -2, 2))]
    if r.random() < 0.6:
        parts += ["-s", fmt(fpos(r, 0.01, 4.0)), fmt(fpos(r, 0.01, 4.0)), fmt(fpos(r, 0.01, 4.0))]
    if r.random() < 0.5:
        parts += ["-t", fmt(fpos(r, -1.0, 1.0)), fmt(fpos(r, -1.0, 1.0)), fmt(fpos(r, -1.0, 1.0))]
    if r.random() < 0.5:
        parts += ["-clamp", r.choice(["on", "off", "1", "0"])]
    if r.random() < 0.5:
        parts += ["-mm", fmt(fpos(r, 0.0, 2.0)), fmt(fpos(r, 0.0, 2.0))]
    if r.random() < 0.5:
        parts += ["-imfchan", r.choice(_imfchans)]
    if r.random() < 0.3:
        parts += ["-type", r.choice(_types)]
    if r.random() < 0.4:
        parts += ["-texres", str(r.choice([64, 128, 256, 512, 1024]))]
    if r.random() < 0.5:
        parts += ["-bm", fmt(fpos(r, 0.01, 8.0))]
    # tinyobj extension
    if r.random() < 0.7:
        parts += ["-colorspace", r.choice(_colorspaces)]
    # Random unknown option to exercise warning path (still valid line)
    if r.random() < 0.2:
        parts += ["-unknown", fmt(fpos(r, -5, 5))]
    return " ".join(parts)


def tex_filename(r: random.Random) -> str:
    base = r.choice(_tex_basenames)
    # Include directories and spaces sometimes
    prefix = "" if r.random() < 0.6 else r.choice(["./", "../", "textures/", "C:/tex/", "/tmp/tex/"])
    name = base
    if r.random() < 0.3:
        name += "_v" + str(r.randint(1, 9))
    if r.random() < 0.2:
        name += " long name"
    ext = r.choice([".png", ".jpg", ".jpeg", ".tga", ".bmp", ".exr", ".hdr"])
    return prefix + name + ext


def map_line(r: random.Random, key: str) -> str:
    opts = tex_options(r)
    fname = tex_filename(r)
    if opts:
        return f"{key} {opts} {fname}\n"
    else:
        return f"{key} {fname}\n"


def material_block(r: random.Random, name: str) -> str:
    lines: List[str] = []
    lines.append(maybe_comment(r))
    lines.append(f"newmtl {name}\n")

    # Scalars
    if r.random() < 0.9:
        lines.append(f"Ns {fmt(fpos(r, 0.0, 1000.0))}\n")
    if r.random() < 0.9:
        lines.append(f"Ni {fmt(fpos(r, 0.1, 4.0))}\n")
    if r.random() < 0.7:
        lines.append(f"illum {r.randint(0, 10)}\n")

    # Colors; sometimes include spectral/xyz alt forms (accepted but often warned)
    if r.random() < 0.95:
        r_, g_, b_ = rand_color(r)
        lines.append(f"Ka {fmt(r_)} {fmt(g_)} {fmt(b_)}\n")
    if r.random() < 0.95:
        r_, g_, b_ = rand_color(r)
        lines.append(f"Kd {fmt(r_)} {fmt(g_)} {fmt(b_)}\n")
    if r.random() < 0.95:
        r_, g_, b_ = rand_color(r)
        lines.append(f"Ks {fmt(r_)} {fmt(g_)} {fmt(b_)}\n")
    if r.random() < 0.7:
        r_, g_, b_ = rand_color(r)
        lines.append(f"Ke {fmt(r_)} {fmt(g_)} {fmt(b_)}\n")

    # Dissolve and transparency; exercise both d and Tr paths
    if r.random() < 0.8:
        lines.append(f"d {fmt(f01(r))}\n")
    if r.random() < 0.5:
        lines.append(f"Tr {fmt(f01(r))}\n")

    # PBR-ish extensions seen in tinyobj material_t
    if r.random() < 0.6:
        lines.append(f"Pr {fmt(f01(r))}\n")  # roughness
    if r.random() < 0.6:
        lines.append(f"Pm {fmt(f01(r))}\n")  # metallic
    if r.random() < 0.4:
        lines.append(f"Ps {fmt(f01(r))}\n")  # sheen
    if r.random() < 0.4:
        lines.append(f"Pc {fmt(f01(r))}\n")  # clearcoat
    if r.random() < 0.4:
        lines.append(f"Pcr {fmt(f01(r))}\n") # clearcoat roughness
    if r.random() < 0.3:
        lines.append(f"aniso {fmt(f01(r))}\n")
    if r.random() < 0.3:
        lines.append(f"anisor {fmt(f01(r))}\n")

    # Transmission/IOR
    if r.random() < 0.5:
        lines.append(f"Tf {fmt(f01(r))} {fmt(f01(r))} {fmt(f01(r))}\n")

    # Texture maps
    if r.random() < 0.9:
        lines.append(map_line(r, "map_Kd"))
    if r.random() < 0.7:
        lines.append(map_line(r, "map_Ks"))
    if r.random() < 0.6:
        lines.append(map_line(r, "map_Ke"))
    if r.random() < 0.6:
        lines.append(map_line(r, "map_d"))
    if r.random() < 0.6:
        lines.append(map_line(r, "map_Pr"))
    if r.random() < 0.6:
        lines.append(map_line(r, "map_Pm"))
    if r.random() < 0.4:
        lines.append(map_line(r, "map_bump"))
    if r.random() < 0.4:
        lines.append(map_line(r, "bump"))
    if r.random() < 0.4:
        lines.append(map_line(r, "disp"))
    if r.random() < 0.4:
        lines.append(map_line(r, "refl"))

    # Misc standard tokens
    if r.random() < 0.5:
        lines.append(f"sharpness {fmt(fpos(r, 0.0, 100.0))}\n")

    # Random whitespace and comments
    if r.random() < 0.3:
        lines.append("\n")
    lines.append(maybe_comment(r))

    return "".join(lines)


def make_mtl(r: random.Random) -> str:
    lines: List[str] = []
    # Optional BOM to test stripping behavior in LoadMtl
    if r.random() < 0.2:
        lines.append("\ufeff")

    # Global comments and blank lines
    for _ in range(r.randint(0, 3)):
        lines.append(maybe_comment(r))
        if r.random() < 0.5:
            lines.append("\n")

    # Number of materials
    n_mats = r.randint(1, 6)
    used_names = set()
    for _ in range(n_mats):
        # Unique material names, occasionally with spaces
        base = r.choice(_material_names)
        suffix = str(r.randint(0, 999)) if r.random() < 0.5 else ""
        name = base + suffix
        if r.random() < 0.2:
            name += " fancy"
        while name in used_names:
            name += "_" + str(r.randint(0, 99))
        used_names.add(name)
        lines.append(material_block(r, name))

    # Trailing whitespace/comments
    for _ in range(r.randint(0, 2)):
        lines.append(maybe_comment(r))
        lines.append("\n")

    text = "".join(lines)
    # Ensure within size limit
    if len(text.encode('utf-8')) > MAX_BYTES:
        # Trim gracefully at line boundary
        enc = text.encode('utf-8')[:MAX_BYTES]
        # Ensure we don't cut multibyte char; backtrack to valid utf-8
        while True:
            try:
                text = enc.decode('utf-8')
                break
            except UnicodeDecodeError:
                enc = enc[:-1]
    return text


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    text = make_mtl(r)
    return text.encode('utf-8')
